ui.css:
.panel { background: #f3ecdd; border: 10px solid #4e4b46; outline: 2px solid #d6cebe; outline-offset: -12px; box-shadow: 0 12px 14px rgba(16,13,10,.45); color: #161412; }
.panel::before { content: ''; position: absolute; left: -16px; right: -16px; bottom: -22px; height: 14px; border-radius: 7px; background: linear-gradient(#4a4540, #141210); }
.bar { height: 22px; background: linear-gradient(90deg, rgba(190,184,170,.75), rgba(190,184,170,.55)); border-radius: 11px 4px 9px 3px; }
.bar > .fill { height: 100%; background: linear-gradient(180deg, #2c2926, #161412 60%, #2c2926); border-radius: 12px 2px 10px 3px; -webkit-mask: linear-gradient(90deg, #000 calc(100% - 16px), transparent); mask: linear-gradient(90deg, #000 calc(100% - 16px), transparent); }
.number { font: 400 40px/1 'Ma Shan Zheng', serif; color: #161412; text-shadow: 0 0 3px #f3ecdd, 0 0 8px #f3ecdd; }
.seal { width: 34px; height: 34px; background: #ce3c26; border-radius: 2px; color: #f9f4e8; font: 400 20px/34px 'Ma Shan Zheng', serif; text-align: center; transform: rotate(-3deg); box-shadow: inset 0 0 0 2px #ce3c26, inset 0 0 0 3px rgba(249,244,232,.7); }
.caption { font: 400 19px 'Zhi Mang Xing', cursive; color: #ce3c26; }
